package main

import (
	"fmt"
	"os"
	"strings"

	"errcheck/errcheck"
)

const (
	exitCodeOk         = 0
	exitCodeUnchecked  = 1
	exitCodeFatalError = 2
)

type tagsFlag []string

func (t *tagsFlag) String() string { return strings.Join(*t, " ") }
func (t *tagsFlag) Set(s string) error {
	// Allow comma or space separated tags.
	var out []string
	for _, part := range strings.FieldsFunc(s, func(r rune) bool { return r == ',' || r == ' ' }) {
		if part != "" {
			out = append(out, part)
		}
	}
	*t = append(*t, out...)
	return nil
}

type ignoreFlag map[string]string

func (i *ignoreFlag) String() string {
	if i == nil || *i == nil {
		return ""
	}
	var parts []string
	for k, v := range *i {
		if k == "" {
			parts = append(parts, v)
		} else {
			parts = append(parts, k+":"+v)
		}
	}
	return strings.Join(parts, ",")
}

func (i *ignoreFlag) Set(s string) error {
	if *i == nil {
		*i = map[string]string{}
	}
	for _, pair := range strings.Split(s, ",") {
		if pair == "" {
			continue
		}
		idx := strings.LastIndex(pair, ":")
		var pkg, re string
		if idx < 0 {
			re = pair
		} else {
			pkg = pair[:idx]
			re = pair[idx+1:]
		}
		(*i)[pkg] = re
	}
	return nil
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	fs := newFlagSet()
	cfg := &errcheck.Config{}
	tags := tagsFlag{}
	ignore := ignoreFlag{}
	var ignorePkg string
	var excludeFile string
	var verbose bool

	fs.BoolVar(&cfg.Blank, "blank", false, "if true, check for errors assigned to blank identifier")
	fs.BoolVar(&cfg.Asserts, "asserts", false, "if true, check for ignored type assertion results")
	fs.BoolVar(&cfg.Abspath, "abspath", false, "print absolute paths to files")
	fs.StringVar(&excludeFile, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	fs.BoolVar(&cfg.ExcludeOnly, "excludeonly", false, "Use only excludes from -exclude file")
	fs.Var(&ignore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	fs.BoolVar(&cfg.IgnoreGenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	fs.StringVar(&ignorePkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	fs.BoolVar(&cfg.IgnoreTests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	fs.StringVar(&cfg.Mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	fs.Var(&tags, "tags", "comma or space-separated list of build tags to include")
	fs.BoolVar(&verbose, "verbose", false, "produce more verbose logging")

	if err := fs.Parse(args); err != nil {
		return exitCodeFatalError
	}
	cfg.Tags = []string(tags)
	cfg.Verbose = verbose

	// ignorepkg - merge into ignore map with "catch all"
	if ignorePkg != "" {
		if ignore == nil {
			ignore = ignoreFlag{}
		}
		for _, pkg := range strings.Split(ignorePkg, ",") {
			if pkg = strings.TrimSpace(pkg); pkg != "" {
				ignore[pkg] = ".*"
			}
		}
	}
	cfg.Ignore = map[string]string(ignore)

	// Load excludes
	if excludeFile != "" {
		f, err := errcheck.ReadExcludes(excludeFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not read exclude file: %s\n", err)
			return exitCodeFatalError
		}
		cfg.Excludes = f
	}

	paths := fs.Args()
	if len(paths) == 0 {
		return exitCodeOk
	}

	result, err := errcheck.Check(cfg, paths)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %s\n", err)
		return exitCodeFatalError
	}
	result.Report(os.Stdout, cfg.Abspath, cfg.Verbose)
	if result.HasIssues() {
		return exitCodeUnchecked
	}
	return exitCodeOk
}

EOF
echo "done"

