)

// newFlagSet creates a flag set configured to behave like Go's default flag.CommandLine
// with os.Args[0] as name, printing usage to stderr on error.
func newFlagSet() *flag.FlagSet {
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	return fs
