package errcheck

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

// goListPackage is the subset of `go list -json` output we care about.
type goListPackage struct {
	Dir            string
	ImportPath     string
	Name           string
	Target         string
	Root           string
	Export         string
	ForTest        string
	Module         *goListModule
	Match          []string
	DepOnly        bool
	Standard       bool
	Goroot         bool
	Stale          bool

	GoFiles           []string
	CgoFiles          []string
	CompiledGoFiles   []string
	IgnoredGoFiles    []string
	TestGoFiles       []string
	XTestGoFiles      []string

	Imports       []string
	ImportMap     map[string]string
	Deps          []string
	TestImports   []string
	XTestImports  []string

	Error     *goListPackageError
	DepsErrors []*goListPackageError
}

type goListPackageError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type goListModule struct {
	Path      string
	Main      bool
	Dir       string
	GoMod     string
	GoVersion string
}

// loadPackages runs `go list` and returns information about the packages
// matched by the given patterns, including their compiled export files and
// their test variants.
type loadedPackage struct {
	info     *goListPackage
	isTest   bool // synthetic test binary package
	fset     *token.FileSet
	files    []*ast.File
	fileNames []string // file path per index
	typesPkg *types.Package
	typesInfo *types.Info
	errors   []error
}

type loader struct {
	cfg *Config
	// indexed by ImportPath (+ForTest variant)
	byID       map[string]*goListPackage
	// export map: ImportPath -> export file path
	exportMap  map[string]string
	// all packages, target + deps
	all []*goListPackage
}

func runGoList(cfg *Config, args []string, patterns []string) ([]*goListPackage, error) {
	fullArgs := []string{"list", "-e", "-json"}
	fullArgs = append(fullArgs, args...)
	if cfg.Mod != "" {
		fullArgs = append(fullArgs, "-mod="+cfg.Mod)
	}
	if len(cfg.Tags) > 0 {
		fullArgs = append(fullArgs, "-tags="+strings.Join(cfg.Tags, " "))
	}
	fullArgs = append(fullArgs, "--")
	fullArgs = append(fullArgs, patterns...)
	cmd := exec.Command("go", fullArgs...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("go list: %s: %s", err, stderr.String())
	}
	var pkgs []*goListPackage
	dec := json.NewDecoder(&stdout)
	for dec.More() {
		p := &goListPackage{}
		if err := dec.Decode(p); err != nil {
			return nil, fmt.Errorf("decode go list output: %w", err)
		}
		pkgs = append(pkgs, p)
	}
	return pkgs, nil
}

func loadAll(cfg *Config, patterns []string) (*loader, []*goListPackage, error) {
	args := []string{"-compiled=true", "-test", "-export", "-deps"}
	pkgs, err := runGoList(cfg, args, patterns)
	if err != nil {
		return nil, nil, err
	}
	l := &loader{
		cfg:       cfg,
		byID:      map[string]*goListPackage{},
		exportMap: map[string]string{},
	}
	for _, p := range pkgs {
		l.all = append(l.all, p)
		id := p.ImportPath
		if p.ForTest != "" {
			id = p.ImportPath // [xxx.test] already baked in
		}
		l.byID[id] = p
		if p.Export != "" {
			// For test variants, map the original ImportPath's test variant too
			l.exportMap[p.ImportPath] = p.Export
		}
	}

	// Target packages: those that were matched by a pattern (Match != nil)
	var targets []*goListPackage
	for _, p := range pkgs {
		if len(p.Match) > 0 && !p.DepOnly {
			targets = append(targets, p)
		}
	}
	return l, targets, nil
}

// Importer returns a types.Importer that reads export data from the loaded packages.
func (l *loader) importer(fromPkg *goListPackage) types.Importer {
	return &exportImporter{
		fromPkg:   fromPkg,
		loader:    l,
		cache:     map[string]*types.Package{},
	}
}

type exportImporter struct {
	fromPkg *goListPackage
	loader  *loader
	cache   map[string]*types.Package
}

func (ei *exportImporter) Import(path string) (*types.Package, error) {
	return ei.ImportFrom(path, "", 0)
}

func (ei *exportImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	if pkg, ok := ei.cache[path]; ok {
		return pkg, nil
	}
	realPath := path
	// Handle vendored paths by looking up the import map.
	if ei.fromPkg != nil && ei.fromPkg.ImportMap != nil {
		if v, ok := ei.fromPkg.ImportMap[path]; ok {
			realPath = v
		}
	}
	exp, ok := ei.loader.exportMap[realPath]
	if !ok {
		return nil, fmt.Errorf("package %q not found in export data", path)
	}
	// Open export file
	f, err := os.Open(exp)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	// Export files have a magic header; go/internal/gcimporter reads them.
	// We use gcexportdata package equivalent via importer.ForCompiler.
	r, err := findExportDataReader(f)
	if err != nil {
		return nil, err
	}
	pkg, err := readExportData(r, ei.loader.fset(), ei.loader.importerPackages(), realPath)
	if err != nil {
		return nil, fmt.Errorf("import %q: %w", path, err)
	}
	ei.cache[path] = pkg
	// Also cache imports of imported packages
	for _, imp := range pkg.Imports() {
		if _, ok := ei.cache[imp.Path()]; !ok {
			ei.cache[imp.Path()] = imp
		}
	}
	return pkg, nil
}

// findExportDataReader navigates past the archive/object header to the export data.
func findExportDataReader(r io.ReadSeeker) (io.Reader, error) {
	// The file might be a raw export data file or an archive.
	// gcexportdata.NewReader would handle both. We re-implement minimal logic.
	// First, peek first bytes.
	return newExportReader(r)
}

