package errcheck

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// goListPackage is the subset of `go list -json` output we care about.
type goListPackage struct {
	Dir        string
	ImportPath string
	Name       string
	Target     string
	Root       string
	Export     string
	ForTest    string
	Module     *goListModule
	Match      []string
	DepOnly    bool
	Standard   bool
	Goroot     bool

	GoFiles         []string
	CgoFiles        []string
	CompiledGoFiles []string
	IgnoredGoFiles  []string
	TestGoFiles     []string
	XTestGoFiles    []string

	Imports      []string
	ImportMap    map[string]string
	Deps         []string
	TestImports  []string
	XTestImports []string

	Error      *goListPackageError
	DepsErrors []*goListPackageError
}

type goListPackageError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type goListModule struct {
	Path      string
	Main      bool
	Dir       string
	GoMod     string
	GoVersion string
}

func runGoList(cfg *Config, args []string, patterns []string) ([]*goListPackage, error) {
	fullArgs := []string{"list", "-e", "-json"}
	fullArgs = append(fullArgs, args...)
	if cfg.Mod != "" {
		fullArgs = append(fullArgs, "-mod="+cfg.Mod)
	}
	if len(cfg.Tags) > 0 {
		fullArgs = append(fullArgs, "-tags="+strings.Join(cfg.Tags, " "))
	}
	fullArgs = append(fullArgs, "--")
	fullArgs = append(fullArgs, patterns...)
	cmd := exec.Command("go", fullArgs...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("%s: %s", err, strings.TrimSpace(stderr.String()))
	}
	var pkgs []*goListPackage
	dec := json.NewDecoder(&stdout)
	for dec.More() {
		p := &goListPackage{}
		if err := dec.Decode(p); err != nil {
			return nil, fmt.Errorf("decode go list output: %w", err)
		}
		pkgs = append(pkgs, p)
	}
	return pkgs, nil
}

// loader holds all the packages we loaded via `go list`.
type loader struct {
	cfg *Config
	// key: importpath (for regular package) or importpath from ForTest context
	byImport map[string]*goListPackage
	// packages marked for test with ForTest=p: we use key "p [p.test]"
	byTestID map[string]*goListPackage
	all      []*goListPackage
}

func loadPackages(cfg *Config, patterns []string) (*loader, []*goListPackage, error) {
	args := []string{"-compiled=false", "-test", "-export", "-deps"}
	pkgs, err := runGoList(cfg, args, patterns)
	if err != nil {
		return nil, nil, err
	}
	l := &loader{
		cfg:      cfg,
		byImport: map[string]*goListPackage{},
		byTestID: map[string]*goListPackage{},
	}
	// Check for errors and build maps
	var loadErrors []string
	for _, p := range pkgs {
		l.all = append(l.all, p)
		if p.ForTest != "" {
			// This is the "in-test" version of package ForTest
			// ID: "ForTest [ForTest.test]" is the go list representation
			l.byTestID[p.ImportPath] = p
		} else {
			l.byImport[p.ImportPath] = p
		}
		if p.Error != nil && !p.DepOnly {
			loadErrors = append(loadErrors, formatPkgError(p))
		}
	}
	// Filter targets
	var targets []*goListPackage
	for _, p := range pkgs {
		if len(p.Match) > 0 && !p.DepOnly {
			targets = append(targets, p)
		}
	}
	if len(loadErrors) > 0 {
		// Concat all errors for reporting
		var names []string
		seen := map[string]bool{}
		for _, p := range pkgs {
			if p.Error != nil && !p.DepOnly {
				if !seen[p.ImportPath] {
					seen[p.ImportPath] = true
					names = append(names, p.ImportPath)
				}
			}
		}
		return nil, nil, fmt.Errorf("errors while loading package %s: %s", strings.Join(names, ", "), strings.Join(loadErrors, " "))
	}
	return l, targets, nil
}

func formatPkgError(p *goListPackage) string {
	if p.Error == nil {
		return ""
	}
	if p.Error.Pos != "" {
		return "[" + p.Error.Pos + ": " + strings.ReplaceAll(p.Error.Err, "\n", " ") + "]"
	}
	return "[-: " + strings.ReplaceAll(p.Error.Err, "\n", " ") + "]"
}

// exportLookup resolves the export file for an import path in the context of
// fromPkg (handling vendor import maps and test binary variants).
func (l *loader) exportLookup(fromPkg *goListPackage) func(path string) (io.ReadCloser, error) {
	return func(path string) (io.ReadCloser, error) {
		real := path
		if fromPkg != nil && fromPkg.ImportMap != nil {
			if v, ok := fromPkg.ImportMap[path]; ok {
				real = v
			}
		}
		// Prefer the test-context variant if we're importing from a test package
		if fromPkg != nil && (fromPkg.ForTest != "" || strings.HasSuffix(fromPkg.ImportPath, ".test")) {
			// Try the [ForTest.test] variant first
			testID := fmt.Sprintf("%s [%s.test]", real, rootOfTest(fromPkg))
			if tp, ok := l.byTestID[testID]; ok && tp.Export != "" {
				return os.Open(tp.Export)
			}
		}
		if p, ok := l.byImport[real]; ok && p.Export != "" {
			return os.Open(p.Export)
		}
		return nil, fmt.Errorf("no export data for %q", path)
	}
}

func rootOfTest(p *goListPackage) string {
	if p.ForTest != "" {
		return p.ForTest
	}
	s := p.ImportPath
	if strings.HasSuffix(s, ".test") {
		return strings.TrimSuffix(s, ".test")
	}
	return s
}

// typeCheck parses and type-checks a single package.
func (l *loader) typeCheck(p *goListPackage, isTestBinary bool) (*checkedPackage, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var fileNames []string
	parseFiles := func(dir string, names []string) error {
		for _, name := range names {
			path := name
			if !filepath.IsAbs(path) {
				path = filepath.Join(dir, name)
			}
			f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
			if err != nil {
				return err
			}
			files = append(files, f)
			fileNames = append(fileNames, path)
		}
		return nil
	}
	if err := parseFiles(p.Dir, p.GoFiles); err != nil {
		return nil, err
	}
	if err := parseFiles(p.Dir, p.CgoFiles); err != nil {
		return nil, err
	}
	if p.ForTest != "" || isTestBinary {
		// include TestGoFiles too (package-internal tests)
		if err := parseFiles(p.Dir, p.TestGoFiles); err != nil {
			return nil, err
		}
	}
	// For the synthetic test binary, we include XTest files as well
	// but we represent that as a separate run.
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Implicits:  map[ast.Node]types.Object{},
		Scopes:     map[ast.Node]*types.Scope{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
	}
	conf := &types.Config{
		Importer:                 importer.ForCompiler(fset, "gc", l.exportLookup(p)),
		Error:                    func(err error) {},
		DisableUnusedImportCheck: true,
	}
	pkg, _ := conf.Check(p.ImportPath, fset, files, info)
	return &checkedPackage{
		info:      p,
		fset:      fset,
		files:     files,
		fileNames: fileNames,
		typesPkg:  pkg,
		typesInfo: info,
	}, nil
}

// typeCheckXTest parses and type checks the external test package (package xxx_test).
func (l *loader) typeCheckXTest(p *goListPackage) (*checkedPackage, error) {
	if len(p.XTestGoFiles) == 0 {
		return nil, nil
	}
	fset := token.NewFileSet()
	var files []*ast.File
	var fileNames []string
	for _, name := range p.XTestGoFiles {
		path := filepath.Join(p.Dir, name)
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil, err
		}
		files = append(files, f)
		fileNames = append(fileNames, path)
	}
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Implicits:  map[ast.Node]types.Object{},
		Scopes:     map[ast.Node]*types.Scope{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
	}
	conf := &types.Config{
		Importer:                 importer.ForCompiler(fset, "gc", l.exportLookup(p)),
		Error:                    func(err error) {},
		DisableUnusedImportCheck: true,
	}
	pkg, _ := conf.Check(p.ImportPath+"_test", fset, files, info)
	return &checkedPackage{
		info:      p,
		fset:      fset,
		files:     files,
		fileNames: fileNames,
		typesPkg:  pkg,
		typesInfo: info,
		xtest:     true,
	}, nil
