		return "[" + p.Error.Pos + ": " + strings.ReplaceAll(p.Error.Err, "\n", " ") + "]"
	}
	return "[-: " + strings.ReplaceAll(p.Error.Err, "\n", " ") + "]"
}

// exportLookup resolves the export file for an import path in the context of
// fromPkg (handling vendor import maps and test binary variants).
func (l *loader) exportLookup(fromPkg *goListPackage) func(path string) (io.ReadCloser, error) {
	return func(path string) (io.ReadCloser, error) {
		real := path
		if fromPkg != nil && fromPkg.ImportMap != nil {
			if v, ok := fromPkg.ImportMap[path]; ok {
				real = v
			}
		}
		// Prefer the test-context variant if we're importing from a test package
		if fromPkg != nil && (fromPkg.ForTest != "" || strings.HasSuffix(fromPkg.ImportPath, ".test")) {
			// Try the [ForTest.test] variant first
			testID := fmt.Sprintf("%s [%s.test]", real, rootOfTest(fromPkg))
			if tp, ok := l.byTestID[testID]; ok && tp.Export != "" {
				return os.Open(tp.Export)
			}
		}
		if p, ok := l.byImport[real]; ok && p.Export != "" {
			return os.Open(p.Export)
		}
		return nil, fmt.Errorf("no export data for %q", path)
	}
}

func rootOfTest(p *goListPackage) string {
	if p.ForTest != "" {
		return p.ForTest
	}
	s := p.ImportPath
	if strings.HasSuffix(s, ".test") {
		return strings.TrimSuffix(s, ".test")
	}
	return s
}

// typeCheck parses and type-checks a single package.
func (l *loader) typeCheck(p *goListPackage, isTestBinary bool) (*checkedPackage, error) {
	fset := token.NewFileSet()
	var files []*ast.File
	var fileNames []string
	parseFiles := func(dir string, names []string) error {
		for _, name := range names {
			path := name
			if !filepath.IsAbs(path) {
				path = filepath.Join(dir, name)
			}
			f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
			if err != nil {
				return err
			}
			files = append(files, f)
			fileNames = append(fileNames, path)
		}
		return nil
	}
	if err := parseFiles(p.Dir, p.GoFiles); err != nil {
		return nil, err
	}
	if err := parseFiles(p.Dir, p.CgoFiles); err != nil {
		return nil, err
	}
	if p.ForTest != "" || isTestBinary {
		// include TestGoFiles too (package-internal tests)
		if err := parseFiles(p.Dir, p.TestGoFiles); err != nil {
			return nil, err
		}
	}
	// For the synthetic test binary, we include XTest files as well
	// but we represent that as a separate run.
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Implicits:  map[ast.Node]types.Object{},
		Scopes:     map[ast.Node]*types.Scope{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
	}
	conf := &types.Config{
		Importer:                 importer.ForCompiler(fset, "gc", l.exportLookup(p)),
		Error:                    func(err error) {},
		DisableUnusedImportCheck: true,
	}
	pkg, _ := conf.Check(p.ImportPath, fset, files, info)
	return &checkedPackage{
		info:      p,
		fset:      fset,
		files:     files,
		fileNames: fileNames,
		typesPkg:  pkg,
		typesInfo: info,
	}, nil
}

// typeCheckXTest parses and type checks the external test package (package xxx_test).
func (l *loader) typeCheckXTest(p *goListPackage) (*checkedPackage, error) {
	if len(p.XTestGoFiles) == 0 {
		return nil, nil
	}
	fset := token.NewFileSet()
	var files []*ast.File
	var fileNames []string
	for _, name := range p.XTestGoFiles {
		path := filepath.Join(p.Dir, name)
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return nil, err
		}
		files = append(files, f)
		fileNames = append(fileNames, path)
	}
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Implicits:  map[ast.Node]types.Object{},
		Scopes:     map[ast.Node]*types.Scope{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
	}
	conf := &types.Config{
		Importer:                 importer.ForCompiler(fset, "gc", l.exportLookup(p)),
		Error:                    func(err error) {},
		DisableUnusedImportCheck: true,
	}
	pkg, _ := conf.Check(p.ImportPath+"_test", fset, files, info)
	return &checkedPackage{
		info:      p,
		fset:      fset,
		files:     files,
		fileNames: fileNames,
		typesPkg:  pkg,
		typesInfo: info,
		xtest:     true,
	}, nil
}
