// HasIssues returns true when at least one unchecked error was found.
func (r *Result) HasIssues() bool { return len(r.Errors) > 0 }

// Report writes the errors to w sorted by file:line:column.
func (r *Result) Report(w io.Writer, abspath, verbose bool) {
	// Dedup by exact position
	seen := map[string]bool{}
	es := make([]UncheckedError, 0, len(r.Errors))
	for _, e := range r.Errors {
		key := e.Pos.Filename + ":" + fmt.Sprintf("%d:%d", e.Pos.Line, e.Pos.Column) + ":" + e.Line
		if seen[key] {
			continue
		}
		seen[key] = true
		es = append(es, e)
	}
	sort.Slice(es, func(i, j int) bool {
		a, b := es[i].Pos, es[j].Pos
		if a.Filename != b.Filename {
			return a.Filename < b.Filename
		}
		if a.Line != b.Line {
			return a.Line < b.Line
		}
		return a.Column < b.Column
	})
	cwd, _ := os.Getwd()
	for _, e := range es {
		name := e.Pos.Filename
		if !abspath {
			if rel, err := filepath.Rel(cwd, name); err == nil {
				name = rel
			}
		} else {
			if abs, err := filepath.Abs(name); err == nil {
				name = abs
			}
		}
		pos := fmt.Sprintf("%s:%d:%d", name, e.Pos.Line, e.Pos.Column)
		if verbose && e.SelectorName != "" {
			fmt.Fprintf(w, "%s:\t%s\t%s\n", pos, e.SelectorName, e.Line)
		} else {
			fmt.Fprintf(w, "%s:\t%s\n", pos, e.Line)
		}
	}
}

// checkedPackage is the result of type-checking a single Go package variant.
