	sort.Slice(es, func(i, j int) bool {
		a, b := es[i].Pos, es[j].Pos
		if a.Filename != b.Filename {
			return a.Filename < b.Filename
		}
		if a.Line != b.Line {
			return a.Line < b.Line
		}
		return a.Column < b.Column
	})
	cwd, _ := os.Getwd()
	for _, e := range es {
		name := e.Pos.Filename
		if !abspath {
			if rel, err := filepath.Rel(cwd, name); err == nil {
				name = rel
			}
		} else {
			if abs, err := filepath.Abs(name); err == nil {
				name = abs
			}
		}
		pos := fmt.Sprintf("%s:%d:%d", name, e.Pos.Line, e.Pos.Column)
		if verbose && e.SelectorName != "" {
			fmt.Fprintf(w, "%s:\t%s\t%s\n", pos, e.SelectorName, e.Line)
		} else {
			fmt.Fprintf(w, "%s:\t%s\n", pos, e.Line)
		}
	}
}

// checkedPackage is the result of type-checking a single Go package variant.
type checkedPackage struct {
	info      *goListPackage
	fset      *token.FileSet
	files     []*ast.File
	fileNames []string
	typesPkg  *types.Package
	typesInfo *types.Info
	xtest     bool
}

// Check loads the given packages and returns any unchecked error call sites.
func Check(cfg *Config, patterns []string) (*Result, error) {
	l, targets, err := loadPackages(cfg, patterns)
	if err != nil {
		return nil, err
	}
	// Build excludes
	excludes, err := buildExcludes(cfg)
	if err != nil {
		return nil, err
	}
	ignoreRegexps, err := compileIgnores(cfg.Ignore)
	if err != nil {
		return nil, err
	}

	result := &Result{}
	// Sort targets by PkgPath for stable verbose output
	sortedTargets := make([]*goListPackage, len(targets))
	copy(sortedTargets, targets)
	sort.SliceStable(sortedTargets, func(i, j int) bool {
		return pkgLogName(sortedTargets[i]) < pkgLogName(sortedTargets[j])
	})

	for _, p := range sortedTargets {
		if cfg.Verbose {
			fmt.Fprintln(os.Stderr, "checking "+pkgLogName(p))
		}
		if p.Name == "" && len(p.GoFiles) == 0 && len(p.CgoFiles) == 0 {
			continue
		}
		cp, err := l.typeCheck(p, p.ForTest != "" || strings.HasSuffix(p.ImportPath, ".test"))
		if err != nil {
			return nil, fmt.Errorf("type-check %s: %w", p.ImportPath, err)
		}
		if cp == nil {
			continue
		}
		v := &visitor{
			cfg:        cfg,
			pkg:        cp,
			excludes:   excludes,
			ignoreRegs: ignoreRegexps,
			result:     result,
		}
		v.run()
		if p.ForTest != "" || strings.HasSuffix(p.ImportPath, ".test") {
			// also check external test files
			xp, err := l.typeCheckXTest(p)
			if err == nil && xp != nil {
				v := &visitor{
					cfg:        cfg,
					pkg:        xp,
					excludes:   excludes,
					ignoreRegs: ignoreRegexps,
					result:     result,
				}
				v.run()
			}
		}
	}
	return result, nil
}

func pkgLogName(p *goListPackage) string {
	if p.ForTest != "" {
		return p.ForTest
	}
	s := p.ImportPath
	// Strip " [xxx]" suffix if present
	if i := strings.Index(s, " ["); i > 0 {
		s = s[:i]
	}
	return s
}

func compileIgnores(m map[string]string) (map[string]*regexp.Regexp, error) {
	out := map[string]*regexp.Regexp{}
	for k, v := range m {
		re, err := regexp.Compile(v)
		if err != nil {
			return nil, fmt.Errorf("ignore regex for %q: %w", k, err)
		}
		out[k] = re
	}
	return out, nil
}
