type visitor struct {
	cfg        *Config
	pkg        *checkedPackage
	excludes   map[string]bool
	ignoreRegs map[string]*regexp.Regexp
	result     *Result

	// Cache whether each file is generated.
	generatedCache map[string]bool
}

func (v *visitor) run() {
	v.generatedCache = map[string]bool{}
	for i, f := range v.pkg.files {
		fname := v.pkg.fileNames[i]
		if v.cfg.IgnoreTests && strings.HasSuffix(fname, "_test.go") {
			continue
		}
		if v.cfg.IgnoreGenerated && isGeneratedFile(f) {
			continue
		}
		v.visitFile(f)
	}
}

func isGeneratedFile(f *ast.File) bool {
	if f == nil {
		return false
	}
	// Go spec: "Code generated by ... DO NOT EDIT." as a single-line comment
	// in a comment group before the package declaration.
	for _, cg := range f.Comments {
		if cg.End() > f.Package {
			continue // comment group is after package declaration
		}
		for _, c := range cg.List {
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			text := strings.TrimPrefix(c.Text, "//")
			text = strings.TrimSpace(text)
			if strings.HasPrefix(text, "Code generated") && strings.HasSuffix(text, "DO NOT EDIT.") {
				return true
			}
		}
	}
	return false
}

func (v *visitor) visitFile(f *ast.File) {
	ast.Inspect(f, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.ExprStmt:
			if call, ok := s.X.(*ast.CallExpr); ok {
				v.visitCallAlone(call)
			}
		case *ast.GoStmt:
			v.visitCallAlone(s.Call)
		case *ast.DeferStmt:
			v.visitCallAlone(s.Call)
		case *ast.AssignStmt:
			v.visitAssign(s)
		}
		return true
	})
}

// visitCallAlone handles a call whose results are entirely discarded (ExprStmt, go, defer).
func (v *visitor) visitCallAlone(call *ast.CallExpr) {
	// Check for type assertion (expression like `x.(T)`) - only via assertion used as call context is impossible
	// so we just handle CallExpr here.
	if v.isExcludedCall(call) {
		return
	}
	ret := v.callReturnTypes(call)
	if len(ret) == 0 {
		return
	}
	found := false
	for _, t := range ret {
		if isErrorType(t) {
			found = true
			break
		}
	}
	if !found {
		return
	}
	v.addIssue(call)
}

func (v *visitor) visitAssign(s *ast.AssignStmt) {
	// Detect blanks
	if len(s.Rhs) == 1 {
		if call, ok := s.Rhs[0].(*ast.CallExpr); ok {
			// Number of LHS should match return count
			if v.cfg.Blank {
				if v.assignHasBlankErrors(s, call) {
					v.addIssue(call)
					return
				}
			}
		}
		// Handle type-assertion  x, ok := y.(T)
		if ta, ok := s.Rhs[0].(*ast.TypeAssertExpr); ok && v.cfg.Asserts {
			// If exactly one LHS, the assertion panics on failure and returns asserted type only
			if len(s.Lhs) == 1 {
				// x = y.(T) or x := y.(T) -- but this is the same as 1-result, we don't report
				// Wait - we DO want to report this!
				// unless LHS is blank
				_ = ta
				v.reportAssertIfNeeded(s, ta)
			}
		}
	}
}

func (v *visitor) reportAssertIfNeeded(s *ast.AssignStmt, ta *ast.TypeAssertExpr) {
	// Report if the single LHS isn't "discarding the ok"
	// Actually, single-LHS form means `x.(T)` panics on failure, and x is asserted T.
	// errcheck reports this as an unchecked type assertion.
	v.result.Errors = append(v.result.Errors, UncheckedError{
		Pos:          v.pkg.fset.Position(s.Pos()),
		Line:         v.sourceLine(s.Pos()),
		IsAssert:     true,
	})
}

func (v *visitor) assignHasBlankErrors(s *ast.AssignStmt, call *ast.CallExpr) bool {
	// Blank detection: at least one LHS is `_` and corresponds to an error return
	ret := v.callReturnTypes(call)
	if len(s.Lhs) != len(ret) {
		return false
	}
	for i, lhs := range s.Lhs {
		id, ok := lhs.(*ast.Ident)
		if !ok {
			continue
		}
		if id.Name != "_" {
			continue
		}
		if isErrorType(ret[i]) {
			return true
		}
	}
	return false
}

// callReturnTypes returns the list of return types of the call expression.
func (v *visitor) callReturnTypes(call *ast.CallExpr) []types.Type {
	tv, ok := v.pkg.typesInfo.Types[call]
	if !ok {
		return nil
	}
	typ := tv.Type
	if typ == nil {
		return nil
	}
	switch t := typ.(type) {
	case *types.Tuple:
		var out []types.Type
		for i := 0; i < t.Len(); i++ {
			out = append(out, t.At(i).Type())
		}
		return out
	default:
		return []types.Type{typ}
	}
}

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	named, ok := t.(*types.Named)
	if !ok {
		// Also handle interface { Error() string }
		if iface, ok := t.Underlying().(*types.Interface); ok {
			return isErrorInterface(iface)
		}
		return false
	}
	obj := named.Obj()
	if obj != nil && obj.Name() == "error" && obj.Pkg() == nil {
		return true
	}
	// Any type that implements `error` interface
	iface, ok := t.Underlying().(*types.Interface)
	if ok && isErrorInterface(iface) {
		return true
	}
	// Check if this type (or pointer) implements error
	return implementsError(t)
}

func isErrorInterface(iface *types.Interface) bool {
	if iface == nil {
		return false
	}
	for i := 0; i < iface.NumMethods(); i++ {
		m := iface.Method(i)
		if m.Name() == "Error" {
			sig, ok := m.Type().(*types.Signature)
			if !ok {
				continue
			}
			if sig.Params().Len() == 0 && sig.Results().Len() == 1 {
				r := sig.Results().At(0).Type()
				if b, ok := r.(*types.Basic); ok && b.Kind() == types.String {
					return true
				}
			}
		}
	}
	return false
}

func implementsError(t types.Type) bool {
	// Build the standard error interface type
	errorType := types.Universe.Lookup("error").Type().Underlying().(*types.Interface)
	if types.Implements(t, errorType) {
		return true
	}
	if p, ok := t.(*types.Pointer); ok {
		if types.Implements(p.Elem(), errorType) {
			return true
		}
	}
	return false
}

func (v *visitor) addIssue(call *ast.CallExpr) {
	pos := v.pkg.fset.Position(call.Pos())
	e := UncheckedError{
		Pos:  pos,
		Line: v.sourceLine(call.Pos()),
	}
	fname, sel := v.callName(call)
	e.FuncName = fname
	e.SelectorName = sel
	v.result.Errors = append(v.result.Errors, e)
}

// sourceLine returns the source text for the line containing pos.
func (v *visitor) sourceLine(pos token.Pos) string {
	p := v.pkg.fset.Position(pos)
	if p.Filename == "" || p.Line == 0 {
		return ""
	}
	f, err := os.Open(p.Filename)
	if err != nil {
		return ""
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	// increase buffer for very long lines
	buf := make([]byte, 0, 64*1024)
	s.Buffer(buf, 1024*1024)
	for i := 1; s.Scan(); i++ {
		if i == p.Line {
			return s.Text()
		}
	}
	return ""
}

// callName returns (fullFuncName, verboseSelector). Full function name uses the
// format used by errcheck's exclude list: pkg.Func, (T).Method, (*T).Method.
func (v *visitor) callName(call *ast.CallExpr) (string, string) {
	switch fn := call.Fun.(type) {
	case *ast.SelectorExpr:
		return v.selectorFuncName(fn)
	case *ast.Ident:
		obj := v.pkg.typesInfo.Uses[fn]
		if obj == nil {
			return "", ""
		}
		if f, ok := obj.(*types.Func); ok {
			return funcFullName(f), ""
		}
		return "", ""
	case *ast.IndexExpr:
		return v.callNameFromExpr(fn.X)
	case *ast.IndexListExpr:
		return v.callNameFromExpr(fn.X)
	case *ast.ParenExpr:
		// (foo)(...)
		return v.callNameFromExpr(fn.X)
	}
	return "", ""
}

func (v *visitor) callNameFromExpr(e ast.Expr) (string, string) {
	switch x := e.(type) {
	case *ast.SelectorExpr:
		return v.selectorFuncName(x)
	case *ast.Ident:
		obj := v.pkg.typesInfo.Uses[x]
		if f, ok := obj.(*types.Func); ok {
			return funcFullName(f), ""
		}
	}
	return "", ""
}

func (v *visitor) selectorFuncName(sel *ast.SelectorExpr) (string, string) {
	selInfo, ok := v.pkg.typesInfo.Selections[sel]
	name := ""
	if ok {
		recv := selInfo.Recv()
		name = typeSelName(recv, sel.Sel.Name)
		if name != "" {
			return name, name
		}
	}
	// Fallback: package-qualified
	if id, ok := sel.X.(*ast.Ident); ok {
		obj := v.pkg.typesInfo.Uses[id]
		if pkgName, ok := obj.(*types.PkgName); ok {
			p := pkgName.Imported().Path()
			return p + "." + sel.Sel.Name, p + "." + sel.Sel.Name
		}
	}
	// Method call fallback using types.Info
	obj := v.pkg.typesInfo.Uses[sel.Sel]
	if f, ok := obj.(*types.Func); ok {
		return funcFullName(f), funcFullName(f)
	}
	return "", ""
}

func typeSelName(recv types.Type, name string) string {
	if recv == nil {
		return ""
	}
	// Unwrap pointer
	star := ""
	base := recv
	if p, ok := recv.(*types.Pointer); ok {
		star = "*"
		base = p.Elem()
	}
	switch b := base.(type) {
	case *types.Named:
		obj := b.Obj()
		if obj == nil {
			return ""
		}
		pkg := ""
		if obj.Pkg() != nil {
			pkg = obj.Pkg().Path() + "."
		}
		return "(" + star + pkg + obj.Name() + ")." + name
	case *types.Interface:
		// Interfaces without a name are unlikely; fall back
		return ""
	}
	return ""
}

func funcFullName(f *types.Func) string {
	if f == nil {
		return ""
	}
	sig, _ := f.Type().(*types.Signature)
	if sig != nil && sig.Recv() != nil {
		return typeSelName(sig.Recv().Type(), f.Name())
	}
	if f.Pkg() != nil {
		return f.Pkg().Path() + "." + f.Name()
	}
	return f.Name()
}

// isExcludedCall returns true if the call should be excluded based on
// configured excludes, ignore regex, etc.
func (v *visitor) isExcludedCall(call *ast.CallExpr) bool {
	full, _ := v.callName(call)
	if full == "" {
		return false
	}
	// Check full name
	if v.excludes[full] {
		return true
	}
	// Check with first arg type qualifier: "pkg.Func(*bytes.Buffer)" etc.
	if len(call.Args) > 0 {
		arg := call.Args[0]
		if s := argQualifier(arg, v.pkg.typesInfo); s != "" {
			key := full + "(" + s + ")"
			if v.excludes[key] {
				return true
			}
		}
		// os.Stdout/os.Stderr literal qualifier
		if s := stdQualifier(arg, v.pkg.typesInfo); s != "" {
			key := full + "(" + s + ")"
			if v.excludes[key] {
				return true
			}
		}
	}
	// Check ignore map (deprecated)
	if re, ok := v.ignoreRegs[""]; ok {
		if re.MatchString(shortNameForIgnore(full)) {
			return true
		}
	}
	pkgPath := pkgPathOf(full)
	if re, ok := v.ignoreRegs[pkgPath]; ok {
		if re.MatchString(shortNameForIgnore(full)) {
			return true
		}
	}
	return false
}

// shortNameForIgnore returns the function name used to match -ignore regex.
// For "pkg.Func" returns "Func". For "(*pkg.T).M" returns "M".
func shortNameForIgnore(full string) string {
	if strings.HasPrefix(full, "(") {
		if i := strings.LastIndex(full, ")."); i > 0 {
			return full[i+2:]
		}
	}
	if i := strings.LastIndex(full, "."); i > 0 {
		return full[i+1:]
	}
	return full
}

func pkgPathOf(full string) string {
	if strings.HasPrefix(full, "(") {
		// (*pkg.T).M or (pkg.T).M
		inner := full
		inner = strings.TrimPrefix(inner, "(")
		inner = strings.TrimPrefix(inner, "*")
		if i := strings.Index(inner, ")"); i > 0 {
			typePart := inner[:i]
			if j := strings.LastIndex(typePart, "."); j > 0 {
				return typePart[:j]
			}
		}
		return ""
	}
	if i := strings.LastIndex(full, "."); i > 0 {
		return full[:i]
	}
	return ""
}

// argQualifier returns the type qualifier for the first argument, e.g. "*bytes.Buffer".
func argQualifier(arg ast.Expr, info *types.Info) string {
	tv, ok := info.Types[arg]
	if !ok {
		return ""
	}
	t := tv.Type
	if t == nil {
		return ""
	}
	return typeQualifiedName(t)
}

func typeQualifiedName(t types.Type) string {
	star := ""
	base := t
	if p, ok := t.(*types.Pointer); ok {
		star = "*"
		base = p.Elem()
	}
	if n, ok := base.(*types.Named); ok {
		obj := n.Obj()
		pkg := ""
		if obj.Pkg() != nil {
			pkg = obj.Pkg().Path() + "."
		}
		return star + pkg + obj.Name()
	}
	return ""
}

func stdQualifier(arg ast.Expr, info *types.Info) string {
	sel, ok := arg.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return ""
	}
	obj := info.Uses[id]
	pkgName, ok := obj.(*types.PkgName)
	if !ok {
		return ""
	}
	if pkgName.Imported().Path() != "os" {
		return ""
	}
	if sel.Sel.Name == "Stdout" || sel.Sel.Name == "Stderr" {
		return "os." + sel.Sel.Name
	}
	return ""
}

