	if re, ok := v.ignoreRegs[""]; ok {
		if re.MatchString(shortNameForIgnore(full)) {
			return true
		}
	}
	pkgPath := pkgPathOf(full)
	if re, ok := v.ignoreRegs[pkgPath]; ok {
		if re.MatchString(shortNameForIgnore(full)) {
			return true
		}
	}
	return false
}

// shortNameForIgnore returns the function name used to match -ignore regex.
// For "pkg.Func" returns "Func". For "(*pkg.T).M" returns "M".
func shortNameForIgnore(full string) string {
	if strings.HasPrefix(full, "(") {
		if i := strings.LastIndex(full, ")."); i > 0 {
			return full[i+2:]
		}
	}
	if i := strings.LastIndex(full, "."); i > 0 {
		return full[i+1:]
	}
	return full
}

func pkgPathOf(full string) string {
	if strings.HasPrefix(full, "(") {
		// (*pkg.T).M or (pkg.T).M
		inner := full
		inner = strings.TrimPrefix(inner, "(")
		inner = strings.TrimPrefix(inner, "*")
		if i := strings.Index(inner, ")"); i > 0 {
			typePart := inner[:i]
			if j := strings.LastIndex(typePart, "."); j > 0 {
				return typePart[:j]
			}
		}
		return ""
	}
	if i := strings.LastIndex(full, "."); i > 0 {
		return full[:i]
	}
	return ""
}

// argQualifier returns the type qualifier for the first argument, e.g. "*bytes.Buffer".
func argQualifier(arg ast.Expr, info *types.Info) string {
	tv, ok := info.Types[arg]
	if !ok {
		return ""
	}
	t := tv.Type
	if t == nil {
		return ""
	}
	return typeQualifiedName(t)
}

func typeQualifiedName(t types.Type) string {
	star := ""
	base := t
	if p, ok := t.(*types.Pointer); ok {
		star = "*"
		base = p.Elem()
	}
	if n, ok := base.(*types.Named); ok {
		obj := n.Obj()
		pkg := ""
		if obj.Pkg() != nil {
			pkg = obj.Pkg().Path() + "."
		}
		return star + pkg + obj.Name()
	}
	return ""
}

func stdQualifier(arg ast.Expr, info *types.Info) string {
	sel, ok := arg.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return ""
	}
	obj := info.Uses[id]
	pkgName, ok := obj.(*types.PkgName)
	if !ok {
		return ""
	}
	if pkgName.Imported().Path() != "os" {
		return ""
	}
	if sel.Sel.Name == "Stdout" || sel.Sel.Name == "Stderr" {
		return "os." + sel.Sel.Name
	}
	return ""
}

