package errcheck

import (
	"bufio"
	"os"
	"strings"
)

// ReadExcludes reads an exclude file. Empty lines and lines starting with // are ignored.
func ReadExcludes(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var out []string
	s := bufio.NewScanner(f)
	for s.Scan() {
		line := strings.TrimSpace(s.Text())
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		out = append(out, line)
	}
	if err := s.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// buildExcludes builds the final exclude set: default exclude list + user exclusions.
func buildExcludes(cfg *Config) (map[string]bool, error) {
	set := map[string]bool{}
	if !cfg.ExcludeOnly {
		for _, s := range defaultExcludes {
			set[s] = true
		}
	}
	for _, s := range cfg.Excludes {
		set[s] = true
	}
	return set, nil
}

// defaultExcludes is the built-in list of stdlib functions/methods that return
// an error but are documented to never fail.
var defaultExcludes = []string{
	// fmt package, formatted printers to stdout/stderr
	"fmt.Print",
	"fmt.Println",
	"fmt.Printf",

	// bytes.Buffer methods
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*bytes.Buffer).WriteString",

	// strings.Builder methods
	"(*strings.Builder).Write",
	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(*strings.Builder).WriteString",

	// hash.Hash
	"(hash.Hash).Write",

	// math/rand
	"math/rand.Read",
	"(*math/rand.Rand).Read",

	// io.Pipe
	"(*io.PipeWriter).CloseWithError",
	"(*io.PipeReader).CloseWithError",
}
EOF
