	info := &types.Info{
		Types: map[ast.Expr]types.TypeAndValue{},
		Uses: map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
	}
	conf := &types.Config{Importer: importer.Default()}
	_, err = conf.Check("main", fset, []*ast.File{f}, info)
	if err != nil { panic(err) }
	for sel, s := range info.Selections {
		if sel.Sel.Name == "Write" {
			fmt.Printf("Sel.X type=%v, Recv=%v, Obj=%v\n", info.Types[sel.X].Type, s.Recv(), s.Obj())
			if f, ok := s.Obj().(*types.Func); ok {
				sig := f.Type().(*types.Signature)
				fmt.Printf("  method recv=%v\n", sig.Recv())
			}
			fmt.Printf("  Indirect=%v, Index=%v\n", s.Indirect(), s.Index())
		}
	}
}
