with open('/workspace/errcheck/visitor.go') as f:
    c = f.read()
old = '''	// Method call: use the actual declared method receiver type.
	if selInfo, ok := v.pkg.typesInfo.Selections[sel]; ok {
		if f, ok := selInfo.Obj().(*types.Func); ok {
			n := funcFullName(f)
			if n != \"\" {
				return n, n
			}
		}
	}
	obj := v.pkg.typesInfo.Uses[sel.Sel]
