		n := funcFullName(f)
		return n, n
	}
	return \"\", \"\"
}'''
new = '''	// Method call. For interfaces we use the selector's receiver type so
	// embedding-based calls produce names relative to the visible interface
	// (e.g. (hash.Hash).Write). For concrete types we use the method's
	// declared receiver (e.g. (*bytes.Buffer).Write).
	if selInfo, ok := v.pkg.typesInfo.Selections[sel]; ok {
		recv := selInfo.Recv()
		if isInterfaceType(recv) {
			if n := typeSelName(recv, sel.Sel.Name); n != \"\" {
