	if f, ok := obj.(*types.Func); ok {
		n := funcFullName(f)
		return n, n
	}
	return \"\", \"\"
}

func isInterfaceType(t types.Type) bool {
	if t == nil {
		return false
	}
	if p, ok := t.(*types.Pointer); ok {
		t = p.Elem()
	}
	_, ok := t.Underlying().(*types.Interface)
	return ok
}'''
